    #define CC_SURFACES_DEBUG_VIEW_SINGLE 1
  #endif
  #ifndef CC_SURFACES_DEBUG_VIEW_COMPOSITE_AND_MISC
    #define CC_SURFACES_DEBUG_VIEW_COMPOSITE_AND_MISC 2
  #endif
#endif
in vec2 a_position;
in vec2 a_texCoord;
in vec4 a_color;
in vec2 a_baseInfo;
in vec2 a_size;
out vec4 color;
out vec2 uv0;
out vec2 baseInfo;
out vec2 size;
vec4 vert () {
  vec4 pos = vec4(a_position,1,1);
  #if USE_LOCAL
    pos = cc_matWorld * pos;
  #endif
  #if USE_PIXEL_ALIGNMENT
    pos = cc_matView * pos;
    pos.xyz = floor(pos.xyz);
    pos = cc_matProj * pos;
  #else
    pos = cc_matViewProj * pos;
  #endif
  uv0 = a_texCoord;
  #if SAMPLE_FROM_RT
    uv0 = cc_cameraPos.w > 1.0 ? vec2(uv0.x, 1.0 - uv0.y) : uv0;
  #endif
  color = a_color;
  baseInfo = a_baseInfo;
  size = a_size;
  return pos;
}
void main() { gl_Position = vert(); }

glsl3.frag:
  precision highp float;
  #if USE_ALPHA_TEST
    layout(std140) uniform ALPHA_TEST_DATA {
      float alphaThreshold;
    };
  #endif
  void ALPHA_TEST (in vec4 color) {
    #if USE_ALPHA_TEST
      if (color.a < alphaThreshold) discard;
    #endif
  }
  void ALPHA_TEST (in float alpha) {
    #if USE_ALPHA_TEST
      if (alpha < alphaThreshold) discard;
    #endif
  }
  in vec4 color;
  in vec2 baseInfo;
  in vec2 size;
  uniform sampler2D texture0;
  uniform sampler2D texture1;
  uniform sampler2D texture2;
  uniform sampler2D texture3;
  uniform sampler2D texture4;
  uniform sampler2D texture5;
  uniform sampler2D texture6;
  uniform sampler2D texture7;
  in vec2 uv0;
vec4 curTexture(vec2 uv0){
    if(baseInfo.y == 0.){
        return texture(texture0 , uv0);
    }else if(baseInfo.y == 1.){
        return texture(texture1 , uv0);
    }else if(baseInfo.y == 2.){
        return texture(texture2 , uv0);
    }else if(baseInfo.y == 3.){
        return texture(texture3 , uv0);
    }else if(baseInfo.y == 4.){
        return texture(texture4 , uv0);
    }else if(baseInfo.y == 5.){
        return texture(texture5 , uv0);
    }else if(baseInfo.y == 6.){
        return texture(texture6 , uv0);
    }else if(baseInfo.y == 7.){
        return texture(texture7 , uv0);
    }
    return texture(texture0 , uv0);
}
  float isBorder(){
    vec4 cur = curTexture(uv0);
    if(cur.r == cur.g && cur.g == cur.b && cur.w < 0.8){
      for(int x = -2 ; x < 3 ; x++){
        for(int y = -2 ; y < 3 ; y++){
          if(x !=0 && y != 0){
            vec2 offset = vec2(uv0.x + float(x) /size.x , uv0.y + float(y)/size.y);
            if(offset.x > 1.0 || offset.x < 0.0 || offset.y > 1.0 || offset.y < 0.0){
            }else{
              vec4 bocor = curTexture(offset);
              if(bocor.w > 0.8){
                return 1.0;
              }
            }
          }
        }
      }
      return 0.;
    }else{
      for(int i = -2 ; i < 3 ; i++){
        for(int j = -2 ; j < 3 ; j++){
          if(i !=0 && j != 0){
            vec2 offset = vec2(uv0.x + float(i) /size.x , uv0.y + float(j)/size.y);
            if(offset.x > 1.0 || offset.x < 0.0 || offset.y > 1.0 || offset.y < 0.0){
            }else{
              vec4 bocor = curTexture(offset);
              if(bocor.r == bocor.g && bocor.g == bocor.b && bocor.w < 0.8){
                return 1.0;
              }
            }
          }
        }
      }
    }
    return 0.;
  }
  vec4 frag () {
    vec4 o = vec4(1, 1, 1, 1);
    vec4 check = curTexture(vec2(0,0));
    if(check.w >0.9){
      o.w = 0.;
    }
    o *= curTexture(uv0);
    ALPHA_TEST(o);
    if(baseInfo.x == 1.0){
        bool h = false;
        float bord = isBorder();
        if(bord > 0.){
            vec4 colorb = vec4(0.803,0.164,0.1411,1);
            o = mix(colorb , o , 0.1);
        }
        if(o.w > 0.7 && color.w < 1. ){
            vec4 colorA = vec4(1,1,1,1);
            o = mix(colorA, o , h ? color.w + 0.2 : color.w);
        }
    }else{
        if(o.w > 0.7 && color.w < 1. ){
            vec4 colorA = vec4(1,1,1,1);
            o = mix(colorA, o , color.w);
        }
    }
    return o;
  }
layout(location = 0) out vec4 cc_FragColor;
void main() { cc_FragColor = frag(); }

